{"path": "variable_length_quantity.py", "content": "def encode(numbers):
    result = []
    for number in numbers:
        if number < 0 or number > 0xFFFFFFFF:
            raise ValueError("number out of 32-bit unsigned range")
        chunk = [number & 0x7F]
        number >>= 7
        while number:
            chunk.append((number & 0x7F) | 0x80)
            number >>= 7
        result.extend(reversed(chunk))
    return result


def decode(bytes_):
    values = []
    current = 0
    incomplete = False
    for byte in bytes_:
        current = (current << 7) | (byte & 0x7F)
        if byte & 0x80:
            incomplete = True
        else:
            values.append(current)
            current = 0
            incomplete = False
    if incomplete:
        raise ValueError("incomplete sequence")
    return values
